Definition leaf_chk_z (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      (Z.eqb pc RETPC && Nat.eqb i 0 && CBA.exit_base_chk Z0T.NF RETPC c ps && CHA.foot_chk Z0T.NF Z0.HDECL c [] [] && CH2.blocks_eqb (nth i Z0.BLS []) []
       && CBA.regions_eqb (CC.cp_F c) CP0 && Nat.leb 40 (CC.cp_nx c)
       && has cells (KWord (SA oE 0) 8 W0S) && has cells (KWord (SA oE 0) 1 B0S) && has cells (KBlob (SA oE 1) szE 0) && has cells (KWord NUL_Z 1 (ELit 0)) && has cells (KRange nE 0 0))%bool
  end.
