Definition gleaf (NF : nat) (d : CH.hdecl) (CPS : list CC.cutpoint) (BLS : list CA.blocks) (RETS : list (nat * nat * nat * Z)) (SCELLS : list (Z * Z * Z)) (GLO GHI : Z)
           (BNEW : list (expr * expr)) (NEWCAP W0 : expr) (CPG1 : list SGP.region)
           (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      match CH2.ret_of RETS i k with
      | Some j =>
          match nth_error CPS j with
          | Some cj =>
              if Z.eqb pc PC_OPNEW then
                let nx := (CC.cp_nx cj - APC.NCS)%nat in let news := news_of (nx + 4) cj in
                (Z.eqb (SR.ps_pc ps) PC_OPNEW && Nat.eqb i 0 && Nat.eqb j 1 && Nat.eqb nx 40 && CBA.regions_eqb (CC.cp_F c) CP0
                 && CH2.blocks_eqb (nth i BLS []) [] && CH2.blocks_eqb (nth j BLS []) BNEW && CHA.foot_chk NF d c [] []
                 && isSome (CHA.custom_chk NF d SCELLS GLO GHI 4112 0 [] [] [] news None c ps cj [] [] BNEW [])
                 && CRB.fresh_news_ok 65536 7077888 d SCELLS GLO GHI cells nx [] [] (nx + 4) NEWCAP news
                 && CL.ps_reg_is ps 10 NEWCAP)%bool
              else if Z.eqb pc PC_MM then
                (Z.eqb (SR.ps_pc ps) PC_MM && Nat.eqb i 1 && Nat.eqb j 3 && CBA.regions_eqb (CC.cp_F c) CPG1 && Nat.leb 45 (CC.cp_nx c)
                 && CH2.blocks_eqb (nth i BLS []) BNEW && CH2.blocks_eqb (nth j BLS []) BNEW && CHA.foot_chk NF d c BNEW []
                 && isSome (CHA.custom_chk NF d SCELLS GLO GHI 2560 0 BNEW [] [(nbE, 0, szE)] NEWS_MM (Some nbE) c ps cj BNEW [] BNEW [])
                 && CL.ps_reg_is ps 10 nbE && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD oE (ELit 1)) && CL.ps_reg_is ps 12 szE && has cells (KBlob (SA oE 1) szE 0))%bool
              else if Z.eqb pc PC_MC then
                (Z.eqb (SR.ps_pc ps) PC_MC && (Nat.eqb i 1 || Nat.eqb i 3) && (Nat.eqb j 2 || Nat.eqb j 4) && CBA.regions_eqb (CC.cp_F c) CPG1 && Nat.leb 45 (CC.cp_nx c)
                 && CH2.blocks_eqb (nth i BLS []) BNEW && CH2.blocks_eqb (nth j BLS []) BNEW && CHA.foot_chk NF d c BNEW []
                 && isSome (CHA.custom_chk NF d SCELLS GLO GHI 2560 0 BNEW [] [(NBSZ, 0, nE)] NEWS_MC (Some NBSZ) c ps cj BNEW [] BNEW [])
                 && CL.ps_reg_is ps 10 NBSZ && CL.ps_reg_is ps 11 qE && CL.ps_reg_is ps 12 nE)%bool
              else false
          | None => false
          end
      | None =>
          (Z.eqb pc RETPC && (Nat.eqb i 2 || Nat.eqb i 4) && CBA.exit_base_chk NF RETPC c ps && CHA.foot_chk NF d c BNEW [] && CH2.blocks_eqb (nth i BLS []) BNEW
           && CBA.regions_eqb (CC.cp_F c) CPG1 && Nat.leb 45 (CC.cp_nx c)
           && has cells (KWord (SA oE 0) 8 W0) && has cells (KWord (SA oE 8) 8 SZN) && has cells (KWord (SA oE 16) 8 nbE)
           && (has cells (KBlob (SA nbE 0) szE 0) || has cells SZ0) && has cells (KBlob (SA NBSZ 0) nE 1) && has cells (KWord NUL_G 1 (ELit 0)))%bool
      end
  end.
