(* [comment removed for export] *)
Lemma append_sso_x : forall (LB : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (o q sp r : Z) (s src : list Z),
  PMSA.cps_asan L ar HI 1040708 r sp PMSA.STR_SCR LB FF LK cr A 0
      (fun R M => 1 <= Z.of_nat (length src) /\ Z.of_nat (length s) + Z.of_nat (length src) <= 22 /\ PMSA.a0 R o /\ PMSA.a1 R q /\ PMSA.a2 R (Z.of_nat (length src)) /\
                  PMSA.str_at L M o (PML.SShort s) /\ PMSA.fobj M FF o 24 /\ PMSA.stksh ar M sp PMSA.STR_SCR /\
